import Hero from "@/components/home/Hero";
import MarqueeTicker from "@/components/home/MarqueeTicker";
import ProductList from "@/components/home/ProductList";
import FadeIn from "@/components/ui/FadeIn";
import type { Product } from "@/types/product";

const API_BASE_URL = process.env.LARAVEL_API_URL ?? "http://127.0.0.1:8000/api";

async function getProducts(): Promise<Product[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/products`, {
      cache: "no-store",
      headers: { Accept: "application/json" },
    });

    if (!response.ok) throw new Error("Không tải được sản phẩm.");

    return await response.json();
  } catch {
    return [];
  }
}

export default async function Home() {
  const productsData = await getProducts();
  const bestSellers = productsData
    .filter((product) => product.isBestSeller || product.is_best_seller)
    .slice(0, 4);
  const sunglasses = productsData.filter((product) => product.category === "Mắt kính").slice(0, 4);
  const frames = productsData.filter((product) => product.category === "Gọng kính").slice(0, 4);
  const accessories = productsData.filter((product) => product.category === "Phụ kiện").slice(0, 4);

  return (
    <div className="bg-background px-4 pt-4 pb-8 sm:pt-6 sm:pb-12 lg:pt-8 lg:pb-16 lg:px-8 min-h-screen">
      <Hero />
      <MarqueeTicker />

      <div className="space-y-12 mt-4">
        <FadeIn direction="up" delay={0.1}>
          <ProductList id="ban-chay" title="Sản phẩm bán chạy nhất" products={bestSellers} />
        </FadeIn>

        <FadeIn direction="up" delay={0.2}>
          <ProductList id="gong-kinh" title="Bộ sưu tập gọng kính" products={frames} viewMoreLink="/category/gong-kinh" />
        </FadeIn>

        <FadeIn direction="up" delay={0.3}>
          <ProductList id="mat-kinh" title="Mắt kính chất lượng" products={sunglasses} viewMoreLink="/category/mat-kinh" />
        </FadeIn>

        <FadeIn direction="up" delay={0.4}>
          <ProductList id="phu-kien" title="Phụ kiện" products={accessories} viewMoreLink="/category/phu-kien" />
        </FadeIn>
      </div>
    </div>
  );
}
